import { useState, Fragment } from 'react';
import { ChevronRight, ChevronDown, X, Menu } from 'lucide-react';
import { NavLink, useLocation } from 'react-router-dom';

interface NavItem {
  label: string;
  href?: string;
  icon?: React.ReactNode;
  badge?: string | number;
  children?: NavItem[];
  disabled?: boolean;
}

interface SidebarProps {
  items: NavItem[];
  logo?: React.ReactNode;
  logoText?: string;
  collapsed?: boolean;
  onToggle?: (collapsed: boolean) => void;
  className?: string;
}

export default function Sidebar({
  items,
  logo,
  logoText = 'App',
  collapsed = false,
  onToggle,
  className = '',
}: SidebarProps) {
  const [openMenus, setOpenMenus] = useState<Set<string>>(new Set());
  const location = useLocation();

  const toggleMenu = (label: string) => {
    setOpenMenus(prev => {
      const next = new Set(prev);
      if (next.has(label)) next.delete(label);
      else next.add(label);
      return next;
    });
  };

  const isActive = (href?: string) => {
    if (!href) return false;
    return location.pathname === href || location.pathname.startsWith(href + '/');
  };

  const renderItem = (item: NavItem, depth = 0, parentLabel = '') => {
    const key = parentLabel ? `${parentLabel}.${item.label}` : item.label;
    const isOpen = openMenus.has(key);
    const hasChildren = item.children && item.children.length > 0;
    const active = isActive(item.href);

    if (hasChildren) {
      return (
        <div key={key}>
          <button
            onClick={() => toggleMenu(key)}
            className={`w-full flex items-center gap-2 px-3 py-2 rounded-lg transition-colors ${active ? 'bg-violet-500/20 text-violet-300' : 'text-gray-300 hover:text-white hover:bg-white/5'}`}
            disabled={item.disabled}
            style={{ paddingLeft: `${depth * 16 + 12}px` }}
            aria-expanded={isOpen}
          >
            {item.icon && <span className="w-5 h-5 flex-shrink-0">{item.icon}</span>}
            {!collapsed && <span className="flex-1 text-left truncate">{item.label}</span>}
            {!collapsed && (
              <ChevronDown className={`w-4 h-4 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            )}
            {item.badge && !collapsed && (
              <span className="text-xs bg-violet-500/20 text-violet-300 px-2 py-0.5 rounded-full">{item.badge}</span>
            )}
          </button>
          {isOpen && !collapsed && (
            <div className="mt-1 space-y-1" style={{ paddingLeft: '8px' }}>
              {item.children!.map(child => renderItem(child, depth + 1, key))}
            </div>
          )}
        </div>
      );
    }

    if (item.href) {
      return (
        <NavLink
          key={key}
          to={item.href}
          className={({ isActive }) =>
            `flex items-center gap-2 px-3 py-2 rounded-lg transition-colors ${isActive ? 'bg-violet-500/20 text-violet-300' : 'text-gray-300 hover:text-white hover:bg-white/5'}`
          }
          style={{ paddingLeft: `${depth * 16 + 12}px` }}
          disabled={item.disabled}
          title={collapsed ? item.label : undefined}
        >
          {item.icon && <span className="w-5 h-5 flex-shrink-0">{item.icon}</span>}
          {!collapsed && <span className="truncate">{item.label}</span>}
          {item.badge && !collapsed && (
            <span className="text-xs bg-violet-500/20 text-violet-300 px-2 py-0.5 rounded-full">{item.badge}</span>
          )}
        </NavLink>
      );
    }

    return null;
  };

  return (
    <aside
      className={`fixed left-0 top-0 z-40 h-screen bg-[#0d1225] border-r border-white/[0.05] transition-all duration-300 flex flex-col ${collapsed ? 'w-16' : 'w-64'} ${className}`}
      aria-label="Main navigation"
    >
      <div className="flex items-center justify-between h-16 px-4 border-b border-white/[0.05]">
        {!collapsed && logo && <div className="flex-shrink-0">{logo}</div>}
        {!collapsed && !logo && logoText && (
          <span className="text-xl font-bold bg-gradient-to-r from-violet-400 to-cyan-400 bg-clip-text text-transparent">{logoText}</span>
        )}
        {collapsed && logo && <div className="flex items-center justify-center">{logo}</div>}
        <button
          onClick={() => onToggle?.(!collapsed)}
          className="flex-shrink-0 p-1.5 rounded-lg text-gray-500 hover:text-white hover:bg-white/5 transition-colors"
          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
        >
          {collapsed ? <ChevronRight className="w-5 h-5" /> : <X className="w-5 h-5" />}
        </button>
      </div>
      <nav className="flex-1 overflow-y-auto p-3 space-y-1" aria-label="Sidebar navigation">
        {items.map(item => renderItem(item))}
      </nav>
      {!collapsed && (
        <div className="p-4 border-t border-white/[0.05]">
          <p className="text-xs text-gray-500 text-center">Use Ctrl+B to toggle</p>
        </div>
      )}
    </aside>
  );
}
